WITH rel_facts(id,k,g,h,v) AS (VALUES (INTEGER '0',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '1',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '2',VARCHAR 'b',VARCHAR 'A',VARCHAR 'Y',CAST(NULL AS integer)),(INTEGER '3',VARCHAR 'b',CAST(NULL AS varchar),VARCHAR 'Y',INTEGER '20'),(INTEGER '4',CAST(NULL AS varchar),CAST(NULL AS varchar),CAST(NULL AS varchar),INTEGER '30'),(INTEGER '5',VARCHAR 'c',VARCHAR 'B',VARCHAR 'X',CAST(NULL AS integer)),(INTEGER '6',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '7',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '8',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '9',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '10',VARCHAR 'b',VARCHAR 'A',VARCHAR 'Y',CAST(NULL AS integer)),(INTEGER '11',VARCHAR 'b',CAST(NULL AS varchar),VARCHAR 'Y',INTEGER '20'),(INTEGER '12',CAST(NULL AS varchar),CAST(NULL AS varchar),CAST(NULL AS varchar),INTEGER '30'),(INTEGER '13',VARCHAR 'c',VARCHAR 'B',VARCHAR 'X',CAST(NULL AS integer)),(INTEGER '14',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '15',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '16',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '17',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '18',VARCHAR 'b',VARCHAR 'A',VARCHAR 'Y',CAST(NULL AS integer)),(INTEGER '19',VARCHAR 'b',CAST(NULL AS varchar),VARCHAR 'Y',INTEGER '20'),(INTEGER '20',CAST(NULL AS varchar),CAST(NULL AS varchar),CAST(NULL AS varchar),INTEGER '30'),(INTEGER '21',VARCHAR 'c',VARCHAR 'B',VARCHAR 'X',CAST(NULL AS integer)),(INTEGER '22',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '23',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '24',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '25',VARCHAR 'a',VARCHAR 'A',VARCHAR 'X',INTEGER '10'),(INTEGER '26',VARCHAR 'b',VARCHAR 'A',VARCHAR 'Y',CAST(NULL AS integer)),(INTEGER '27',VARCHAR 'b',CAST(NULL AS varchar),VARCHAR 'Y',INTEGER '20'),(INTEGER '28',CAST(NULL AS varchar),CAST(NULL AS varchar),CAST(NULL AS varchar),INTEGER '30'),(INTEGER '29',VARCHAR 'c',VARCHAR 'B',VARCHAR 'X',CAST(NULL AS integer)),(INTEGER '30',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5'),(INTEGER '31',VARCHAR 'd',VARCHAR 'B',CAST(NULL AS varchar),INTEGER '5')), rel_dims(k,label) AS (VALUES (VARCHAR 'a',VARCHAR 'first'),(VARCHAR 'a',VARCHAR 'second'),(VARCHAR 'b',VARCHAR 'only'),(CAST(NULL AS varchar),VARCHAR 'null-key'),(VARCHAR 'z',VARCHAR 'unmatched'),(VARCHAR 'c',CAST(NULL AS varchar))) SELECT f.id, d.label FROM rel_facts f JOIN rel_dims d ON f.k = d.k